// mobile menu
const burger = document.getElementById("burger"),
  menu = document.getElementById("menu");
burger.addEventListener("click", () => {
  const o = menu.classList.toggle("open");
  burger.setAttribute("aria-expanded", o);
});
menu
  .querySelectorAll("a:not(.sub-toggle)")
  .forEach((a) =>
    a.addEventListener("click", () => menu.classList.remove("open")),
  );

// dropdown menus: first tap opens the sub-menu, links inside navigate
(function () {
  const items = [...document.querySelectorAll(".menu>li.has-sub")];
  const closeAll = (except) =>
    items.forEach((li) => {
      if (li !== except) {
        li.classList.remove("open");
        li.querySelector(".sub-toggle").setAttribute("aria-expanded", "false");
      }
    });
  items.forEach((li) => {
    const t = li.querySelector(".sub-toggle");
    t.addEventListener("click", (e) => {
      e.preventDefault();
      const desk = innerWidth > 960;
      const o = desk ? true : !li.classList.contains("open");
      closeAll(li);
      li.classList.toggle("open", o);
      t.setAttribute("aria-expanded", String(o));
    });
    li.querySelectorAll(".sub a").forEach((a) =>
      a.addEventListener("click", () => {
        closeAll();
        document.getElementById("menu").classList.remove("open");
        document
          .getElementById("burger")
          .setAttribute("aria-expanded", "false");
      }),
    );
  });
  document.addEventListener("click", (e) => {
    if (!e.target.closest(".menu>li.has-sub")) closeAll();
  });
  // desktop: hovering any menu item (top level or sub-page) opens that section, no click needed
  let lastTouch = 0;
  addEventListener(
    "touchstart",
    () => {
      lastTouch = Date.now();
    },
    { passive: true },
  );
  const hoverOK = () => innerWidth > 960 && Date.now() - lastTouch > 800;
  document.querySelectorAll('.menu a[href^="#"]:not(.nav-emp)').forEach((a) => {
    const h = a.getAttribute("href");
    if (h.length < 2) return;
    let dw;
    a.addEventListener("mouseenter", () => {
      if (!hoverOK()) return;
      clearTimeout(dw);
      dw = setTimeout(() => {
        const el = document.querySelector(h);
        if (!el) return;
        jumpTo(el);
        document
          .querySelectorAll(".menu a.hovering")
          .forEach((x) => x.classList.remove("hovering"));
        a.classList.add("hovering");
      }, 200);
    });
    a.addEventListener("mouseleave", () => clearTimeout(dw));
  });
  // desktop: open on hover, close shortly after the pointer leaves
  items.forEach((li) => {
    let tm;
    const t = li.querySelector(".sub-toggle");
    li.addEventListener("mouseenter", () => {
      if (innerWidth <= 960 || Date.now() - lastTouch < 800) return;
      clearTimeout(tm);
      closeAll(li);
      li.classList.add("open");
      t.setAttribute("aria-expanded", "true");
    });
    li.addEventListener("mouseleave", () => {
      if (innerWidth <= 960) return;
      tm = setTimeout(() => {
        li.classList.remove("open");
        t.setAttribute("aria-expanded", "false");
        if (li.contains(document.activeElement)) document.activeElement.blur();
      }, 200);
    });
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeAll();
  });
})();

// hero slider: autoplay with progress tabs, arrows, swipe, pause on hover
(function () {
  const hero = document.getElementById("top-hero"),
    slides = [...hero.querySelectorAll(".hs")],
    tabs = [...hero.querySelectorAll(".hs-tabs button")];
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches,
    DUR = 3000;
  let cur = 0,
    t;
  hero.style.setProperty("--dur", DUR + "ms");
  function go(i) {
    i = (i + slides.length) % slides.length;
    slides[cur].classList.remove("on");
    tabs[cur].classList.remove("on");
    tabs[cur].setAttribute("aria-selected", "false");
    cur = i;
    slides[cur].classList.add("on");
    const tb = tabs[cur];
    const bar = tb.querySelector("i");
    bar.style.animation = "none";
    void bar.offsetWidth;
    bar.style.animation = "";
    tb.classList.add("on");
    tb.setAttribute("aria-selected", "true");
    const n = slides[cur].querySelector(".ht-num");
    if (n) countUp(n);
    schedule();
  }
  function schedule() {
    clearTimeout(t);
    if (!reduce && !hero.classList.contains("paused"))
      t = setTimeout(() => go(cur + 1), DUR);
  }
  function countUp(el) {
    const end = +el.dataset.count;
    if (reduce) {
      el.textContent = end;
      return;
    }
    const t0 = performance.now();
    (function f(n) {
      const k = Math.min(1, (n - t0) / 1400);
      el.textContent = Math.round(end * (1 - Math.pow(1 - k, 3)));
      if (k < 1) requestAnimationFrame(f);
    })(t0);
  }
  tabs.forEach((b, i) => b.addEventListener("click", () => go(i)));
  document
    .getElementById("hs-prev")
    .addEventListener("click", () => go(cur - 1));
  document
    .getElementById("hs-next")
    .addEventListener("click", () => go(cur + 1));
  hero.addEventListener("mouseenter", () => {
    hero.classList.add("paused");
    clearTimeout(t);
  });
  hero.addEventListener("mouseleave", () => {
    hero.classList.remove("paused");
    schedule();
  });
  let x0 = null;
  hero.addEventListener(
    "touchstart",
    (e) => {
      x0 = e.touches[0].clientX;
    },
    { passive: true },
  );
  hero.addEventListener("touchend", (e) => {
    if (x0 === null) return;
    const dx = e.changedTouches[0].clientX - x0;
    if (Math.abs(dx) > 50) go(cur + (dx < 0 ? 1 : -1));
    x0 = null;
  });
  hero.addEventListener("keydown", (e) => {
    if (e.key === "ArrowRight") go(cur + 1);
    if (e.key === "ArrowLeft") go(cur - 1);
  });
  countUp(slides[0].querySelector(".ht-num"));
  schedule();
})();

// stat count-up (values already visible at rest)
document.querySelectorAll("[data-count]").forEach((el) => {
  const end = +el.dataset.count,
    dec = +(el.dataset.dec || 0),
    pre = el.dataset.prefix || "",
    suf = el.dataset.suffix || "";
  const io = new IntersectionObserver(([e]) => {
    if (!e.isIntersecting) return;
    io.disconnect();
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const t0 = performance.now();
    (function f(n) {
      const k = Math.min(1, (n - t0) / 1400),
        v = end * (1 - Math.pow(1 - k, 3));
      el.textContent =
        pre +
        (dec ? v.toFixed(dec) : Math.round(v).toLocaleString("en-IN")) +
        suf;
      if (k < 1) requestAnimationFrame(f);
    })(t0);
  });
  io.observe(el);
});

