let spec = -1,
  limit = 25;
const chipsEl = document.getElementById("chips"),
  rowsEl = document.getElementById("rows"),
  qEl = document.getElementById("q"),
  moreEl = document.getElementById("more"),
  shownEl = document.getElementById("shown"),
  headEl = document.getElementById("spec-head");
chipsEl.innerHTML =
  '<button class="stab" type="button" role="tab" aria-selected="true" data-s="-1">All products <span>250+</span></button>' +
  SPECIALTIES.map(
    (s, i) =>
      `<button class="stab" type="button" role="tab" aria-selected="false" data-s="${i}">${s[0]} <span>${s[1].length}</span></button>`,
  ).join("");
const esc = (t) =>
  String(t).replace(
    /[&<>"]/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
  );
function render() {
  const q = qEl.value.trim().toLowerCase();
  const base = spec < 0 ? PRODUCTS.map((p, i) => i) : SPECIALTIES[spec][1];
  const list = base.filter((i) => {
    const p = PRODUCTS[i];
    return (
      !q || (p[0] + " " + p[1] + " " + (p[5] || "")).toLowerCase().includes(q)
    );
  });
  headEl.innerHTML =
    spec < 0
      ? "<b>All products</b><span>The complete Aspen range, A–Z by brand.</span>"
      : `<b>${esc(SPECIALTIES[spec][0])}</b><span>${SPECIALTIES[spec][1].length} brands for this specialty.</span>`;
  rowsEl.innerHTML =
    list
      .slice(0, limit)
      .map((i) => {
        const p = PRODUCTS[i];
        const mo = MONOMAP[i];
        return `<tr><td class="b"><div class="bcell">${IMGS[i] ? `<button class="thumb-btn" type="button" data-i="${i}" aria-label="View photo of ${esc(p[0])}"><img src="${IMGS[i]}" alt=""></button>` : ""}<div>${mo ? `<button type="button" class="brand-link" data-mono="${i}" title="Open product monograph">${esc(p[0])}</button>` : esc(p[0])}<br><span class="ftag">${esc(p[4])}</span></div></div></td><td class="c">${esc(p[1])}</td><td class="cat-c">${esc(p[5] || "")}</td><td>${esc(p[2])}</td><td class="mono-c">${mo ? `<button type="button" class="mono-btn" data-mono="${i}">Monograph</button>` : '<span class="na">–</span>'}</td></tr>`;
      })
      .join("") ||
    '<tr><td colspan="5" class="c">No products match your search. Try a different brand or salt name.</td></tr>';
  shownEl.textContent = `Showing ${Math.min(limit, list.length)} of ${spec < 0 && !q ? "250+" : list.length} products`;
  moreEl.hidden = list.length <= limit;
}
chipsEl.addEventListener("click", (e) => {
  const b = e.target.closest(".stab");
  if (!b) return;
  spec = +b.dataset.s;
  limit = 25;
  chipsEl
    .querySelectorAll(".stab")
    .forEach((c) => c.setAttribute("aria-selected", String(c === b)));
  b.scrollIntoView({ block: "nearest", inline: "center" });
  render();
});
qEl.addEventListener("input", () => {
  limit = 25;
  render();
});
moreEl.addEventListener("click", () => {
  limit += 50;
  render();
});
render();
const tk = document.getElementById("ticker");
const cards = Object.keys(IMGS)
  .filter((i, n, arr) => arr.findIndex((j) => IMGS[j] === IMGS[i]) === n)
  .map(
    (i) =>
      `<button class="pcard" type="button" data-i="${i}"><img src="${IMGS[i]}" alt="${esc(PRODUCTS[i][0])} pack" loading="lazy"><b>${esc(PRODUCTS[i][0])}</b><i>${esc(PRODUCTS[i][1])}</i></button>`,
  )
  .join("");
tk.innerHTML = cards + cards;

// lightbox
const lb = document.getElementById("lb"),
  lbImg = document.getElementById("lb-img"),
  lbCap = document.getElementById("lb-cap");
function openLb(i) {
  const p = PRODUCTS[i];
  lbImg.src = IMGS[i];
  lbImg.alt = p[0] + " pack photo";
  lbCap.innerHTML = `<b>${esc(p[0])}</b><span>${esc(p[1])}</span><span class="ftag">${esc(p[2])} · ${p[4]}</span>`;
  lb.hidden = false;
  document.getElementById("lb-close").focus();
}
document.addEventListener("click", (e) => {
  const t = e.target.closest("[data-i]");
  if (t) openLb(+t.dataset.i);
  if (e.target === lb || e.target.closest("#lb-close")) lb.hidden = true;
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") lb.hidden = true;
});

// production line illustration
(function () {
  const cv = document.getElementById("line");
  if (!cv) return;
  const ctx = cv.getContext("2d");
  const btn = document.getElementById("line-toggle");
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  let playing = !reduce,
    t0 = performance.now(),
    tAcc = 0,
    last = t0;
  btn.textContent = playing ? "Pause" : "Play";
  btn.setAttribute("aria-pressed", String(!playing));
  btn.addEventListener("click", () => {
    playing = !playing;
    btn.textContent = playing ? "Pause" : "Play";
    btn.setAttribute("aria-pressed", String(!playing));
    if (playing) {
      last = performance.now();
      requestAnimationFrame(loop);
    }
  });
  const v = (n) =>
    getComputedStyle(document.documentElement).getPropertyValue(n).trim();
  function rr(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }
  function draw(t) {
    const W = cv.clientWidth,
      H = cv.clientHeight,
      d = devicePixelRatio || 1;
    if (cv.width !== Math.round(W * d) || cv.height !== Math.round(H * d)) {
      cv.width = Math.round(W * d);
      cv.height = Math.round(H * d);
    }
    ctx.setTransform(d, 0, 0, d, 0, 0);
    const bg = v("--surface"),
      ink = v("--ink"),
      mut = v("--muted"),
      line = v("--line"),
      sp = v("--spruce-2"),
      gold = v("--gold"),
      soft = v("--gold-soft"),
      dark = v("--spruce");
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);
    // clean-room wall panels
    ctx.strokeStyle = line;
    ctx.lineWidth = 1;
    for (let x = 0; x < W; x += W / 12) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, H * 0.62);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.moveTo(0, H * 0.62);
    ctx.lineTo(W, H * 0.62);
    ctx.stroke();
    // belt
    const by = H * 0.66,
      bh = Math.max(8, H * 0.05);
    ctx.fillStyle = dark;
    rr(W * 0.04, by, W * 0.92, bh, bh / 2);
    ctx.fill();
    const rollers = Math.floor(W / 28),
      off = (t * 0.06) % 28;
    ctx.fillStyle = mut;
    for (let i = 0; i < rollers + 2; i++) {
      const x = W * 0.04 + ((i * 28 + off) % (W * 0.92));
      ctx.beginPath();
      ctx.arc(x, by + bh / 2, bh * 0.22, 0, 7);
      ctx.fill();
    }
    // legs
    ctx.fillStyle = line;
    for (const x of [0.08, 0.3, 0.52, 0.74, 0.92]) {
      ctx.fillRect(W * x, by + bh, 4, H * 0.18);
    }
    const st = { hop: 0.12, coat: 0.36, press: 0.6, box: 0.84 };
    const fs = Math.max(9, Math.min(12, W / 70));
    ctx.font = `500 ${fs}px "IBM Plex Mono", monospace`;
    ctx.textAlign = "center";
    ctx.fillStyle = mut;
    [
      ["COMPRESSION", st.hop],
      ["COATING", st.coat],
      ["BLISTER PACKING", st.press],
      ["CARTONING", st.box],
    ].forEach(([l, x]) => ctx.fillText(l, W * x, H * 0.95));
    // hopper + press head
    const hx = W * st.hop;
    ctx.fillStyle = sp;
    ctx.beginPath();
    ctx.moveTo(hx - W * 0.05, H * 0.12);
    ctx.lineTo(hx + W * 0.05, H * 0.12);
    ctx.lineTo(hx + W * 0.015, H * 0.4);
    ctx.lineTo(hx - W * 0.015, H * 0.4);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = soft;
    rr(hx - W * 0.04, H * 0.15, W * 0.08, H * 0.07, 4);
    ctx.fill();
    const punch = Math.max(0, Math.sin(t / 180)) * H * 0.12;
    ctx.fillStyle = dark;
    ctx.fillRect(hx - 3, H * 0.4, 6, H * 0.06 + punch * 0.5);
    // coating drum
    const cx = W * st.coat,
      cy = H * 0.38,
      cr = Math.min(W * 0.06, H * 0.2);
    ctx.fillStyle = dark;
    ctx.beginPath();
    ctx.arc(cx, cy, cr, 0, 7);
    ctx.fill();
    ctx.strokeStyle = gold;
    ctx.lineWidth = 2;
    for (let k = 0; k < 6; k++) {
      const a = t / 600 + (k * Math.PI) / 3;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + Math.cos(a) * cr * 0.85, cy + Math.sin(a) * cr * 0.85);
      ctx.stroke();
    }
    ctx.fillStyle = gold;
    for (let k = 0; k < 8; k++) {
      const a = -t / 450 + k * 0.8;
      ctx.beginPath();
      ctx.ellipse(
        cx + Math.cos(a) * cr * 0.5,
        cy + Math.sin(a) * cr * 0.5,
        4,
        2.6,
        a,
        0,
        7,
      );
      ctx.fill();
    }
    ctx.fillStyle = line;
    ctx.fillRect(cx - 3, cy + cr, 6, by - cy - cr);
    // blister press
    const px = W * st.press;
    const pr = (Math.sin(t / 260) + 1) / 2;
    ctx.fillStyle = dark;
    rr(px - W * 0.05, H * 0.1, W * 0.1, H * 0.12, 6);
    ctx.fill();
    ctx.fillStyle = mut;
    ctx.fillRect(px - W * 0.035, H * 0.22, 6, by - H * 0.22);
    ctx.fillRect(px + W * 0.035 - 6, H * 0.22, 6, by - H * 0.22);
    ctx.fillStyle = sp;
    rr(px - W * 0.045, H * 0.24 + pr * (by - H * 0.36), W * 0.09, H * 0.08, 4);
    ctx.fill();
    // carton stack
    const bx = W * st.box;
    ctx.fillStyle = soft;
    ctx.strokeStyle = gold;
    ctx.lineWidth = 1.5;
    for (let k = 0; k < 3; k++) {
      rr(
        bx - W * 0.05 + k * W * 0.03,
        H * 0.32 - k * H * 0.06,
        W * 0.05,
        H * 0.08,
        3,
      );
      ctx.fill();
      ctx.stroke();
    }
    // moving items
    const speed = 0.055,
      gap = 60,
      start = W * 0.06,
      end = W * 0.96;
    const n = Math.ceil((end - start) / gap) + 1;
    for (let i = 0; i < n; i++) {
      const x = start + ((t * speed + i * gap) % (end - start));
      const y = by - 2;
      if (x < W * st.coat) {
        ctx.fillStyle = "#FFFFFF";
        ctx.strokeStyle = mut;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.ellipse(x, y - 5, 7, 4.5, 0, 0, 7);
        ctx.fill();
        ctx.stroke();
      } else if (x < W * st.press) {
        ctx.fillStyle = gold;
        ctx.beginPath();
        ctx.ellipse(x, y - 5, 7, 4.5, 0, 0, 7);
        ctx.fill();
      } else if (x < W * st.box) {
        ctx.fillStyle = "#E9EEF0";
        ctx.strokeStyle = mut;
        ctx.lineWidth = 1;
        rr(x - 16, y - 10, 32, 10, 3);
        ctx.fill();
        ctx.stroke();
        ctx.fillStyle = gold;
        for (let k = 0; k < 4; k++) {
          ctx.beginPath();
          ctx.arc(x - 10.5 + k * 7, y - 5, 2.4, 0, 7);
          ctx.fill();
        }
      } else {
        ctx.fillStyle = soft;
        ctx.strokeStyle = gold;
        ctx.lineWidth = 1.5;
        rr(x - 14, y - 18, 28, 18, 3);
        ctx.fill();
        ctx.stroke();
      }
    }
    ctx.textAlign = "left";
  }
  function loop(now) {
    if (!playing) return;
    tAcc += now - last;
    last = now;
    draw(tAcc);
    requestAnimationFrame(loop);
  }
  draw(0);
  if (playing) requestAnimationFrame(loop);
  addEventListener("resize", () => draw(tAcc));
})();

// employee login: opens CBO links
(function () {
  const m = document.getElementById("emp");
  const open = () => {
    m.hidden = false;
    setTimeout(() => m.querySelector(".emp-btn").focus(), 30);
  };
  const close = () => {
    m.hidden = true;
  };
  const eo = document.getElementById("emp-open");
  if (eo) eo.addEventListener("click", open);
  document.querySelectorAll("[data-emp]").forEach((b) =>
    b.addEventListener("click", (e) => {
      e.preventDefault();
      open();
    }),
  );
  document.getElementById("emp-close").addEventListener("click", close);
  m.addEventListener("click", (e) => {
    if (e.target === m) close();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !m.hidden) close();
  });
})();

// instant section jump with a soft fade (no scrolling animation)
function jumpTo(el) {
  const off = () =>
    el === document.body || el.id === "top-hero" || el.id === "top"
      ? 0
      : el.getBoundingClientRect().top +
        scrollY -
        (document.querySelector("header.nav").offsetHeight + 16);
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  el.querySelectorAll(".reveal.pre").forEach((x) => x.classList.remove("pre"));
  const f = document.getElementById("jump-fade");
  if (!reduce && f) {
    f.classList.add("on");
    setTimeout(() => {
      window.scrollTo(0, off());
      requestAnimationFrame(() => {
        window.scrollTo(0, off());
        f.classList.remove("on");
      });
    }, 120);
  } else window.scrollTo(0, off());
}
document.addEventListener("click", (e) => {
  const a = e.target.closest('a[href^="#"]');
  if (!a) return;
  const h = a.getAttribute("href");
  if (h.length < 2) return;
  const el = document.querySelector(h);
  if (!el || a.classList.contains("sub-toggle")) return;
  e.preventDefault();
  jumpTo(el);
  history.replaceState(null, "", h);
});

// motion: reveal on scroll, header state, progress bar, back-to-top, active menu
(function () {
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const sel =
    ".sec-head,.form,.fd-card,.qc-card,.partner,.value,.cx,.g-item,.mv-card,.ab-item,.ab-block,.steps li,.fd-quality,.fd-cta,.direction,.careers,.certband,.line-fig,.stat,.facts-card,.cat,.rnd-copy,.rnd-hero,.contact .cinfo,.contact form";
  if (!reduce && "IntersectionObserver" in window) {
    const els = [...document.querySelectorAll(sel)];
    const io = new IntersectionObserver(
      (es) =>
        es.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.remove("pre");
            io.unobserve(e.target);
          }
        }),
      { rootMargin: "0px 0px -8% 0px" },
    );
    els.forEach((el, i) => {
      el.classList.add("reveal");
      const r = el.getBoundingClientRect();
      if (r.top > innerHeight) {
        el.classList.add("pre");
        el.style.transitionDelay = (i % 3) * 80 + "ms";
        io.observe(el);
      }
    });
  }
  const hdr = document.querySelector("header.nav"),
    bar = document.getElementById("progress"),
    top = document.getElementById("to-top");
  const links = [
    ...document.querySelectorAll('.menu>li>a[href^="#"]:not(.nav-emp)'),
  ];
  const secs = links
    .map((a) => document.querySelector(a.getAttribute("href")))
    .filter(Boolean);
  function onScroll() {
    const y = scrollY,
      h = document.documentElement.scrollHeight - innerHeight;
    hdr.classList.toggle("scrolled", y > 10);
    bar.style.width = (h > 0 ? (y / h) * 100 : 0) + "%";
    top.classList.toggle("show", y > 700);
    let cur = null;
    secs.forEach((sec) => {
      if (sec.getBoundingClientRect().top < 140) cur = sec;
    });
    links.forEach((a) =>
      a.classList.toggle(
        "active",
        cur && a.getAttribute("href") === "#" + cur.id,
      ),
    );
  }
  addEventListener("scroll", onScroll, { passive: true });
  onScroll();
  top.addEventListener("click", () => jumpTo(document.body));
})();

// product monographs
(function () {
  const box = document.getElementById("mono"),
    body = document.getElementById("mono-body");
  const e = (t) =>
    String(t).replace(
      /[&<>"]/g,
      (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
    );
  const link = (t) =>
    e(t).replace(
      /(https?:\/\/[^\s)]+)/g,
      '<a href="$1" target="_blank" rel="noopener">$1</a>',
    );
  function renderBlocks(bl) {
    let h = "",
      i = 0;
    while (i < bl.length) {
      const b = bl[i];
      if (b[0] === "kv") {
        let r = "";
        while (i < bl.length && bl[i][0] === "kv") {
          const v = /^molecular formula/i.test(bl[i][1])
            ? e(bl[i][2]).replace(/([A-Za-z)\]])(\d+)/g, "$1<sub>$2</sub>")
            : e(bl[i][2]);
          r += `<tr><th scope="row">${e(bl[i][1])}</th><td>${v}</td></tr>`;
          i++;
        }
        h += `<table class="mono-kv">${r}</table>`;
        continue;
      }
      if (b[0] === "li") {
        let r = "";
        while (i < bl.length && bl[i][0] === "li") {
          r += `<li>${e(bl[i][1])}</li>`;
          i++;
        }
        h += `<ul>${r}</ul>`;
        continue;
      }
      if (b[0] === "ref") {
        let r = "";
        while (i < bl.length && bl[i][0] === "ref") {
          r += `<li>${link(bl[i][2])}</li>`;
          i++;
        }
        h += `<ol class="mono-refs">${r}</ol>`;
        continue;
      }
      if (b[0] === "h") h += `<h4>${e(b[1])}</h4>`;
      else h += `<p>${e(b[1]).replace(/^([^:]{2,40}):/, "<b>$1:</b>")}</p>`;
      i++;
    }
    return h;
  }
  const brandsFor = (no) =>
    Object.keys(MONOMAP)
      .filter((k) => MONOMAP[k] === no)
      .map((k) => PRODUCTS[k][0]);
  function show(no, pi) {
    const [name, sub, meta, secs, disc] = MONO[no];
    const p = pi != null ? PRODUCTS[pi] : null;
    const brands = [...new Set(brandsFor(no))];
    body.innerHTML = `<p class="mono-kicker">Product Monograph · No. ${no}</p>
      ${p ? `<h2 id="mono-title">${e(p[0])}</h2><p class="mono-api">${e(name)}${sub ? " · " + e(sub) : ""}</p>` : `<h2 id="mono-title">${e(name)}</h2>${sub ? `<p class="mono-api">${e(sub)}</p>` : ""}`}
      ${p ? `<div class="mono-brand"><div><small>Brand composition</small><span>${e(p[1])}</span></div><div><small>Pack</small><span>${e(p[2])}</span></div></div>` : ""}
      <dl class="mono-meta">${meta.map(([k, v]) => `<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join("")}</dl>
      ${brands.length ? `<p class="mono-brands"><b>Aspen brands:</b> ${brands.map(e).join(", ")}</p>` : ""}
      <nav class="mono-toc" aria-label="Sections">${secs.map(([t], k) => `<button type="button" data-ms="${k}">${k + 1}. ${e(t)}</button>`).join("")}</nav>
      ${secs.map(([t, bl], k) => `<section class="mono-sec" id="ms-${k}"><h3><span>${k + 1}</span>${e(t)}</h3>${renderBlocks(bl)}</section>`).join("")}
      ${disc ? `<p class="mono-disc">${e(disc)}</p>` : ""}`;
    box.hidden = false;
    document.body.style.overflow = "hidden";
    body.scrollTop = 0;
    document.getElementById("mono-close").focus();
  }
  function index() {
    const items = Object.keys(MONO).sort((a, b) =>
      MONO[a][0].localeCompare(MONO[b][0]),
    );
    body.innerHTML = `<p class="mono-kicker">Aspen Pharmaceuticals</p><h2 id="mono-title">Product Monographs</h2><p class="mono-api">${items.length} detailed scientific monographs by active ingredient. Select one to read it.</p>
      <input type="search" id="mono-q" class="mono-q" placeholder="Search ingredient or brand" aria-label="Search monographs">
      <ul class="mono-index" id="mono-index">${items
        .map((no) => {
          const b = [...new Set(brandsFor(no))];
          return `<li data-k="${e((MONO[no][0] + " " + b.join(" ")).toLowerCase())}"><button type="button" data-open="${no}"><b>${e(MONO[no][0])}</b><span>${e(b.join(", "))}</span></button></li>`;
        })
        .join("")}</ul>`;
    box.hidden = false;
    document.body.style.overflow = "hidden";
    body.scrollTop = 0;
    const q = document.getElementById("mono-q");
    q.focus();
    q.addEventListener("input", () => {
      const v = q.value.trim().toLowerCase();
      document
        .querySelectorAll("#mono-index li")
        .forEach((li) => (li.hidden = v && !li.dataset.k.includes(v)));
    });
  }
  function close() {
    box.hidden = true;
    document.body.style.overflow = "";
  }
  document.addEventListener("click", (ev) => {
    const b = ev.target.closest("[data-mono]");
    if (b) {
      ev.preventDefault();
      const i = +b.dataset.mono;
      show(MONOMAP[i], i);
      return;
    }
    const o = ev.target.closest("[data-open]");
    if (o) {
      show(o.dataset.open, null);
      return;
    }
    const ms = ev.target.closest("[data-ms]");
    if (ms) {
      const t = document.getElementById("ms-" + ms.dataset.ms);
      if (t) body.scrollTop = t.offsetTop - body.offsetTop - 12;
      return;
    }
    if (ev.target.closest("#mono-all")) {
      index();
      return;
    }
    if (ev.target === box || ev.target.closest("#mono-close")) close();
  });
  document.addEventListener("keydown", (ev) => {
    if (ev.key === "Escape" && !box.hidden) close();
  });
})();

// Contact form — EmailJS
// MANUAL SETUP: replace the three placeholder values below with your EmailJS details.
const EMAILJS_PUBLIC_KEY = "32Z054BH4zCCak8_m";
const EMAILJS_SERVICE_ID = "service_lughj7d";
const EMAILJS_TEMPLATE_ID = "template_hln62yi";

const contactForm = document.getElementById("cform");

if (contactForm) {
  emailjs.init({ publicKey: EMAILJS_PUBLIC_KEY });

  contactForm.addEventListener("submit", async (event) => {
    event.preventDefault();

    const submitButton = document.getElementById("contact-submit");
    const submitText = document.getElementById("contact-submit-text");
    const successMessage = document.getElementById("ok");
    const errorMessage = document.getElementById("contact-error");
    const timestamp = document.getElementById("f-submitted-at");

    successMessage.hidden = true;
    errorMessage.hidden = true;
    errorMessage.style.display = "none";

    if (!contactForm.checkValidity()) {
      contactForm.reportValidity();
      return;
    }

    timestamp.value = new Date().toLocaleString("en-IN", {
      dateStyle: "medium",
      timeStyle: "short",
      timeZone: "Asia/Kolkata",
    });

    submitButton.disabled = true;
    submitText.textContent = "Sending…";

    try {
      await emailjs.sendForm(
        EMAILJS_SERVICE_ID,
        EMAILJS_TEMPLATE_ID,
        contactForm,
      );
      contactForm.reset();
      successMessage.hidden = false;
    } catch (error) {
      console.error("EmailJS contact form error:", error);
      errorMessage.hidden = false;
      errorMessage.style.display = "inline";
    } finally {
      submitButton.disabled = false;
      submitText.textContent = "Send message";
    }
  });
}
